217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner != null) {
222	            Pet pet = owner.getPet(petId);
223	            if (pet != null) {
224	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
225	            }
226	        }
227	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	    }
229	
230	    /**
231	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
232	     * The address is normalized in place (so a required-field check that follows rejects an
233	     * address blank after normalization), the required fields are checked, the telephone and
234	     * email are normalized in place, and the resulting owner is rejected when its derived
235	     * identity key already belongs to another owner. Each rule
236	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
237	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
238	     * to be mapped and saved.
239	     *
240	     * @param ownerFieldsDto the submitted owner fields, normalized in place
241	     */
242	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
243	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
244	        validateRequiredFields(ownerFieldsDto);
245	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
246	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
247	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
248	        rejectDuplicateIdentity(ownerFieldsDto);
249	        rejectCityAtCapacity(ownerFieldsDto.getCity());
250	        rejectDailyLimitExceeded(registrationDate);
251	    }
252	
253	    /**
254	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
255	     * falls on a business day. The date supplied on the request is used when present, otherwise the
256	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
257	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
258	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
259	     * membership number's year segment, the per-day create limit) is computed against.
260	     *
261	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
262	     * @return the effective registration date rolled forward to the next business day
263	     */
264	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
265	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
266	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
267	        return toBusinessDay(effective);
268	    }
269	
270	    /**
271	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
272	     * following Monday, while a weekday is returned unchanged.
273	     *
274	     * @param date the date to adjust
275	     * @return the same date when it is a weekday, otherwise the next Monday
276	     */
277	    private LocalDate toBusinessDay(LocalDate date) {
278	        java.time.DayOfWeek day = date.getDayOfWeek();
279	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
280	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
281	        }
282	        return date;
283	    }
284	
285	    /**
286	     * The maximum number of owners that may be created on a single day. Once this many owners
287	     * already carry today's {@code registrationDate}, no further owner may be created today.
288	     */
289	    private static final long DAILY_OWNER_LIMIT = 100L;
290	
291	    /**
292	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
293	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
294	     * date the new owner would be stored with, so owners are capped per business day. When the limit
295	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
296	     * advice renders as a 429 Too Many Requests response.
297	     *
298	     * @param registrationDate the adjusted business-day registration date of the owner being created
299	     */
300	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
301	        long count = this.clinicService.findAllOwners().stream()
302	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
303	            .count();
304	        if (count >= DAILY_OWNER_LIMIT) {
305	            throw new DailyOwnerLimitExceededException(registrationDate);
306	        }
307	    }
308	
309	    /**
310	     * The number of owners that may carry a single day's {@code registrationDate} before that day
311	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
312	     * the create and read responses report {@code bulkSignupWarning} true for that date.
313	     */
314	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
315	
316	    /**
317	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
318	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
319	     * count is taken against the same adjusted date owners are stored with, mirroring the
320	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
321	     *
322	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
323	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
324	     */
325	    private boolean bulkSignupWarning(LocalDate registrationDate) {
326	        if (registrationDate == null) {
327	            return false;
328	        }
329	        long count = this.clinicService.findAllOwners().stream()
330	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
331	            .count();
332	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
333	    }
334	
335	    /**
336	     * The maximum number of owners a single city may hold. Once a city already contains this
337	     * many owners, no further owner may be created in it.
338	     */
339	    private static final long CITY_OWNER_CAPACITY = 50L;
340	
341	    /**
342	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
343	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
344	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
345	     * which the exception advice renders as a 409 Conflict response.
346	     *
347	     * @param city the city of the owner being created
348	     */
349	    private void rejectCityAtCapacity(String city) {
350	        long count = this.clinicService.findAllOwners().stream()
351	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
352	            .count();
353	        if (count >= CITY_OWNER_CAPACITY) {
354	            throw new CityCapacityExceededException(city);
355	        }
356	    }
357	
358	    /**
359	     * Builds the customer code assigned to a newly created owner. The code is formatted as
360	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
361	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
362	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
363	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
364	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
365	     *
366	     * @param city the owner's city
367	     * @param lastName the owner's last name
368	     * @return the formatted customer code
369	     */
370	    private String nextCustomerCode(String city, String lastName) {
371	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
372	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
373	        long sequence = this.clinicService.findAllOwners().stream()
374	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
375	            .count() + 1L;
376	        return String.format("%s-%s-%04d", city3, last3, sequence);
377	    }
378	
379	    /**
380	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
381	     * with the owner being created, compared case-insensitively. The count is taken before the
382	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
383	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
384	     *
385	     * @param firstName the first name of the owner being created
386	     * @param lastName the last name of the owner being created
387	     * @return the number of pre-existing owners sharing the same first and last name
388	     */
389	    private int countNamesakes(String firstName, String lastName) {
390	        return (int) this.clinicService.findAllOwners().stream()
391	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
392	                && lastName.equalsIgnoreCase(existing.getLastName()))
393	            .count();
394	    }
395	
396	    /**
397	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
398	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
399	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
400	     * the names of every offending field, which the exception advice renders as a 400 response
401	     * with an {@code errors} array.
402	     *
403	     * @param ownerFieldsDto the submitted owner fields
404	     */
405	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
406	        List<String> missing = new ArrayList<>();
407	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
408	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
409	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
410	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
411	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
412	        if (!missing.isEmpty()) {
413	            throw new RequiredFieldsMissingException(missing);
414	        }
415	    }
416	
417	    private void addIfBlank(List<String> missing, String fieldName, String value) {
418	        if (value == null || value.isBlank()) {
419	            missing.add(fieldName);
420	        }
421	    }
422	
423	    /**
424	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
425	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
426	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
427	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
428	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
429	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
430	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
431	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
432	     *
433	     * @param telephone the submitted telephone value
434	     * @return the normalized E.164 telephone
435	     */
436	    private String normalizeTelephone(String telephone) {
437	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
438	        String e164;
439	        if (cleaned.startsWith("+")) {
440	            e164 = "+" + cleaned.substring(1);
441	        } else {
442	            String national = cleaned;
443	            if (national.startsWith("0")) {
444	                national = national.substring(1);
445	            }
446	            e164 = "+61" + national;
447	        }
448	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
449	            throw new InvalidFieldsException(List.of("telephone"));
450	        }
451	        validateNationalNumberLength(e164);
452	        return e164;
453	    }
454	
455	    /**
456	     * The required national-number length (the digits after the country code) for each country
457	     * code we recognize: {@code '+61'} (Australia) requires 9 national digits and {@code '+1'}
458	     * (NANP) requires 10. Keyed by the country-code digits without the leading {@code '+'}.
459	     */
460	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
461	        java.util.Map.of("61", 9, "1", 10);
462	
463	    /**
464	     * Validates the national-number length of an already syntactically valid E.164 telephone
465	     * against its country code. For each recognized country code the digits following the code
466	     * must have exactly the expected length ({@code '+61'} => 9 national digits, {@code '+1'} =>
467	     * 10). When the country code is recognized but the national number is the wrong length an
468	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
469	     * response naming the {@code telephone} field. A country code that is not recognized carries
470	     * no per-country length rule and is left to the general 8-to-15-digit E.164 check.
471	     *
472	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
473	     */
474	    private void validateNationalNumberLength(String e164) {
475	        String digits = e164.substring(1);
476	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
477	            .filter(entry -> digits.startsWith(entry.getKey()))
478	            // longest matching country code wins, so a shorter code cannot shadow a longer one
479	            .max(java.util.Comparator.comparingInt(entry -> entry.getKey().length()))
480	            .ifPresent(entry -> {
481	                int nationalLength = digits.length() - entry.getKey().length();
482	                if (nationalLength != entry.getValue()) {
483	                    throw new InvalidFieldsException(List.of("telephone"));
484	                }
485	            });
486	    }
487	
488	    /**
489	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
490	     * and a domain containing at least one dot, none of the parts holding whitespace or a
491	     * second {@code @}.
492	     */
493	    private static final java.util.regex.Pattern EMAIL_PATTERN =
494	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
495	
496	    /**
497	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
498	     * accepted and returned unchanged. When present it must be a syntactically valid address;
499	     * the value is stored and returned lower-cased. When present but invalid an
500	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
501	     * response naming the {@code email} field.
502	     *
503	     * @param email the submitted email value, or {@code null} when omitted
504	     * @return the lower-cased email, or {@code null} when none was supplied
505	     */
506	    private String normalizeEmail(String email) {
507	        if (email == null) {
508	            return null;
509	        }
510	        String trimmed = email.trim();
511	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
512	            throw new InvalidFieldsException(List.of("email"));
513	        }
514	        return canonicalEmail(trimmed);
515	    }
516	
517	    /**
518	     * Reduces an email to the canonical form used both to store it and to compare it against
519	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
520	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
521	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
522	     * value read back off an existing owner without risk of rejecting it. This is the single
523	     * definition of email identity: two emails denote the same address exactly when they
524	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
525	     * an email already on an existing owner can be compared for equality after both pass through
526	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
527	     *
528	     * @param email the email to canonicalize, or {@code null} when none was supplied
529	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
530	     */
531	    private String canonicalEmail(String email) {
532	        if (email == null) {
533	            return null;
534	        }
535	        return email.trim().toLowerCase(java.util.Locale.ROOT);
536	    }
537	
538	    /**
539	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
540	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
541	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
542	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
543	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
544	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
545	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
546	     * 400 response naming the {@code postcode} field.
547	     *
548	     * @param postcode the submitted postcode, or {@code null} when omitted
549	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
550	     */
551	    private void validatePostcode(String postcode, String city) {
552	        if (postcode == null) {
553	            return;
554	        }
555	        if (!postcode.matches("^[0-9]{4}$")) {
556	            throw new InvalidFieldsException(List.of("postcode"));
557	        }
558	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
559	        if (range != null) {
560	            int value = Integer.parseInt(postcode);
561	            if (value < range[0] || value > range[1]) {
562	                throw new InvalidFieldsException(List.of("postcode"));
563	            }
564	        }
565	    }
566	
567	    /**
568	     * Rejects a new owner whose derived identity key is already used by any existing owner. All
569	     * duplicate detection is consolidated into this single key (see
570	     * {@link Owner#identityKey(String, String, String)}): the normalized E.164 telephone, the
571	     * canonical (trimmed, lower-cased) email and the household identifier the owner would receive,
572	     * joined by {@code '|'}. The submitted telephone and email have already been normalized in
573	     * place, and the household identifier is the value {@link #assignHousehold} would later store
574	     * (see {@link #prospectiveHouseholdId(OwnerFieldsDto)}). An owner is a duplicate only when its
575	     * whole key equals an existing owner's, so a difference in any part — for example two members
576	     * of one household with different telephones — yields distinct keys and is allowed. When a
577	     * match is found a {@link DuplicateIdentityException} is thrown, which the exception advice
578	     * renders as a 409 Conflict response.
579	     *
580	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
581	     */
582	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
583	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
584	            canonicalEmail(ownerFieldsDto.getEmail()), prospectiveHouseholdId(ownerFieldsDto));
585	        boolean taken = this.clinicService.findAllOwners().stream()
586	            .anyMatch(existing -> identityKey.equals(Owner.identityKey(existing.getTelephone(),
587	                canonicalEmail(existing.getEmail()), existing.getHouseholdId())));
588	        if (taken) {
589	            throw new DuplicateIdentityException(identityKey);
590	        }
591	    }
592	
593	    /**
594	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
595	     * set to {@code true}. The identifier is the one the owner would receive
596	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
597	     * household identity so every owner in the same household resolves to the same stable value.
598	     * The new owner receives that value, and any existing household mates that do not yet carry it
599	     * are updated so the whole household shares one identifier. When the request did not opt in the
600	     * owner is left without a household identifier.
601	     *
602	     * @param owner the newly created owner, mutated in place with its household identifier
603	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
604	     */
605	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
606	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
607	        if (householdId == null) {
608	            return;
609	        }
610	        owner.setHouseholdId(householdId);
611	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
612	            if (!householdId.equals(mate.getHouseholdId())) {
613	                mate.setHouseholdId(householdId);
614	                this.clinicService.saveOwner(mate);
615	            }
616	        }
617	    }
618	
619	    /**
620	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
621	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
622	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
623	     * from the owner's household identity (its {@code lastName} and {@code address}, see
624	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
625	     * later store and every household mate resolves to the same identifier. When the request did not
626	     * opt in the owner belongs to no shared household and {@code null} is returned.
627	     *
628	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
629	     * @return the household identifier the owner would receive, or {@code null} when it shares none
630	     */
631	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
632	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
633	            return null;
634	        }
635	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
636	    }
637	
638	    /**
639	     * Derives the stable {@code householdId} shared by every owner in the household identified by
640	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
641	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
642	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
643	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
644	     *
645	     * @param lastName the household's last name
646	     * @param address the household's address
647	     * @return the deterministic household identifier
648	     */
649	    private String householdIdFor(String lastName, String address) {
650	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
651	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
652	        try {
653	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
654	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
655	            StringBuilder sb = new StringBuilder();
656	            for (int i = 0; i < 8; i++) {
657	                sb.append(String.format("%02X", digest[i]));
658	            }
659	            return "HH-" + sb;
660	        }
661	        catch (java.security.NoSuchAlgorithmException e) {
662	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
663	        }
664	    }
665	
666	    /**
667	     * Counts the owners that belong to the household identified by the given {@code householdId},
668	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
669	     * of owners, so after a create it reflects the household's size including the newly persisted
670	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
671	     * household and yields {@code 0}.
672	     *
673	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
674	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
675	     */
676	    private int countHouseholdMembers(String householdId) {
677	        if (householdId == null) {
678	            return 0;
679	        }
680	        return (int) this.clinicService.findAllOwners().stream()
681	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
682	            .count();
683	    }
684	
685	    /**
686	     * Finds every existing owner that shares a household with the given {@code lastName} and
687	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
688	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
689	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
690	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
691	     * every rule that reasons about households.
692	     *
693	     * @param lastName the last name to match on
694	     * @param address the address to match on
695	     * @return the owners sharing the household, in encounter order (possibly empty)
696	     */
697	    private List<Owner> findHouseholdMates(String lastName, String address) {
698	        String normalizedLastName = collapseWhitespace(lastName);
699	        String normalizedAddress = normalizeAddress(address);
700	        return this.clinicService.findAllOwners().stream()
701	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
702	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
703	            .toList();
704	    }
705	
706	    /**
707	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
708	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
709	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
710	     *
711	     * @param value the value to collapse, or {@code null}
712	     * @return the whitespace-collapsed value, never {@code null}
713	     */
714	    private String collapseWhitespace(String value) {
715	        if (value == null) {
716	            return "";
717	        }
718	        return value.trim().replaceAll("\\s+", " ");
719	    }
720	
721	    /**
722	     * Common street-type abbreviations expanded during address normalization, keyed by their
723	     * upper-cased token.
724	     */
725	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
726	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
727	
728	    /**
729	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
730	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
731	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
732	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
733	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
734	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
735	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
736	     * everywhere an address is stored or compared.
737	     *
738	     * @param address the submitted address value, or {@code null}
739	     * @return the normalized address, never {@code null}
740	     */
741	    private String normalizeAddress(String address) {
742	        if (address == null) {
743	            return "";
744	        }
745	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
746	        if (collapsed.isEmpty()) {
747	            return "";
748	        }
749	        String[] tokens = collapsed.split(" ");
750	        StringBuilder sb = new StringBuilder(collapsed.length());
751	        for (int i = 0; i < tokens.length; i++) {
752	            if (i > 0) {
753	                sb.append(' ');
754	            }
755	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
756	        }
757	        return sb.toString();
758	    }
759	}
