221	    /**
222	     * Handles {@link CityCapacityExceededException} thrown when a request tries to create an owner
223	     * whose city already contains the maximum number of owners. Returns a 409 Conflict.
224	     *
225	     * @param e The {@link CityCapacityExceededException} to be handled
226	     * @param request {@link HttpServletRequest} object referring to the current request.
227	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
228	     */
229	    @ExceptionHandler(CityCapacityExceededException.class)
230	    @ResponseBody
231	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
232	        HttpStatus status = HttpStatus.CONFLICT;
